@Override
public void startDocument() throws SAXException {
    if (documentStarted) {
        throw new SAXException("StrictXHTMLValidator: startDocument called twice");
    }
    if (documentEnded) {
        throw new SAXException("StrictXHTMLValidator: startDocument after endDocument");
    }
    documentStarted = true;
    super.startDocument();
}
